var canvasSize;
let tx = 0;
let ty = 10;

let tekst, tekst2, tekst3;
let alice = "In another moment down went after it, never once considering how in the world she was to get out again. The rabbit-hole went straight on like a tunnel for some way, and then dipped suddenly down, so suddenly that had not a moment to think about stopping herself before she found herself falling down a very deep well. Either the well was very deep, or she fell very slowly, for she had plenty of time as she went down to look about her and to wonder what was going to happen next. First, she tried to look down and make out what she was coming to, but it was too dark to see anything; then she looked at the sides of the well, and noticed that they were filled with cupboards and book-shelves; here and there she saw maps and pictures hung upon pegs. She took down a jar from one of the shelves as she passed; it was labelled ORANGE MARMALADE', but to her great disappointment it was empty: she did not like to drop the jar for fear of killing somebody, so managed to put it into one of the cupboards as she fell past it. Well!' thought to herself, after such a fall as this, I shall think nothing of tumbling down stairs! How brave they'll all think me at home! Why, I wouldn't say anything about it, even if I fell off the top of the house!' (Which was very likely true.) Down, down, down. Would the fall never come to an end! I wonder how many miles I've fallen by this time?' she said aloud. I must be getting somewhere near the centre of the earth. Let me see: that would be four thousand miles down, I think--' (for, you see, had learnt several things of this sort in her lessons in the schoolroom, and though this was not a very good opportunity for showing off her knowledge, as there was no one to listen to her, still it was good practice to say it over) --yes, that's about the right distance--but then I wonder what Latitude or Longitude I've got to?' ( had no idea what Latitude was, or Longitude either, but thought they were nice grand words to say.) Presently she began again. I wonder if I shall fall right through the earth! How funny it'll seem to come out among the people that walk with their heads downward! The Antipathies, I think--' (she was rather glad there was no one listening, this time, as it didn't sound at all the right word) --but I shall have to ask them what the name of the country is, you know. Please, Ma'am, is this New Zealand or Australia?' (and she tried to curtsey as she spoke--fancy curtseying as you're falling through the air! Do you think you could manage it?) And what an ignorant little girl she'll think me for asking! No, it'll never do to ask: perhaps I shall see it written up somewhere.' Down, down, down. There was nothing else to do, so soon began talking again. Dinah'll miss me very much to-night, I should think!' (Dinah was the cat.) I hope they'll remember her saucer of milk at tea-time. Dinah my dear! I wish you were down here with me! There are no mice in the air, I'm afraid, but you might catch a bat, and that's very like a mouse, you know. But do cats eat bats, I wonder?' And here began to get rather sleepy, and went on saying to herself, in a dreamy sort of way, Do cats eat bats? Do cats eat bats?' and sometimes, Do bats eat cats?' for, you see, as she couldn't answer either question, it didn't much matter which way she put it. She felt that she was dozing off, and had just begun to dream that she was walking hand in hand with Dinah, and saying to her very earnestly, Now, Dinah, tell me the truth: did you ever eat a bat?' when suddenly, thump! thump! down she came upon a heap of sticks and dry leaves, and the fall was over. was not a bit hurt, and she jumped up on to her feet in a moment: she looked up, but it was all dark overhead; before her was another long passage, and the White Rabbit was still in sight, hurrying down it. There was not a moment to be lost: away went like the wind, and was just in time to hear it say, as it turned a corner, Oh my ears and whiskers, how late it's getting!' She was close behind it when she turned the corner, but the Rabbit was no longer to be seen: she found herself in a long, low hall, which was lit up by a row of lamps hanging from the roof. There were doors all round the hall, but they were all locked; and when had been all the way down one side and up the other, trying every door, she walked sadly down the middle, wondering how she was ever to get out again. Suddenly she came upon a little three-legged table, all made of solid glass; there was nothing on it except a tiny golden key, and 's first thought was that it might belong to one of the doors of the hall; but, alas! either the locks were too large, or the key was too small, but at any rate it would not open any of them. However, on the second time round, she came upon a low curtain she had not noticed before, and behind it was a little door about fifteen inches high: she tried the little golden key in the lock, and to her great delight it fitted! ";


function setup() {
	canvasSize = max(windowWidth, windowHeight);
	createCanvas( canvasSize, canvasSize);

  tekst = createGraphics(canvasSize, canvasSize);
	tekst2 = createGraphics(canvasSize, canvasSize);
  tekst3  = createGraphics(canvasSize, canvasSize);
  noiseSeed(get_random(0, 99999));
  frameRate(60);

  bg = color(248, 244, 233);

	let ts = canvasSize*0.02;
	tekst.textFont('Georgia');
	tekst.textSize(ts);

  let ts2 = canvasSize*0.04;
  tekst2.textFont('Georgia');
	tekst2.textSize(ts2);

	let ts3 = canvasSize*0.01;
	tekst3.textFont('Georgia');
	tekst3.textSize(ts3);

  let reci = split(alice, ' ');
  let trenutnax = textWidth("I"); 
  let trenutnay =  ts;

	for (let i=0; i<1100; i++) {
		let rnd_rec = reci[floor(get_random(0, reci.length))];
    tekst.text(rnd_rec, trenutnax, trenutnay);
		trenutnax += (ts/11)*textWidth(" "+rnd_rec);
		if (trenutnax  >= canvasSize  ) {
			trenutnax = 0;
			trenutnay += 1.1*ts;
		}  
	}

	trenutnax = 0;
	trenutnay =  ts2;
	for (let i=0; i<300; i++) {
		let rnd_rec = reci[floor(get_random(0, reci.length))];
    tekst2.text(rnd_rec, trenutnax, trenutnay);
		trenutnax += (ts2/11)*textWidth(" "+rnd_rec);
		if (trenutnax  >= canvasSize  ) {
			trenutnax = 0;
			trenutnay += 1.1*ts2;
		}   
	}

	trenutnax = 0;
	trenutnay =  ts3;
	for (let i=0; i<4100; i++) {
		let rnd_rec = reci[floor(get_random(0, reci.length))];
    tekst3.text(rnd_rec, trenutnax, trenutnay);
		trenutnax += (ts3/11)*textWidth(" "+rnd_rec);
		if (trenutnax  >= canvasSize  ) {
			trenutnax = 0;
			trenutnay += 1.1*ts3;
		}   
	}

}


function draw() {

   background(bg);
	 // image( tekst2, 0,0);


	 ty = 2; 	
   noStroke();
   for (let i=0; i<20; i++) {
		 tx = 1;
	   for (let j=0; j<20; j++) {
		  let rnd = map(noise(tx, ty), 0,1, 0, 100) 
		  tx+=0.1;

		  if (rnd<50){
				push();
				translate( i*canvasSize/20, j*canvasSize/20);
				rotate(random(0,PI));
				beginShape();
				for(let u=0; u<TWO_PI; u+=(Math.max(0.001, Math.abs(PI/4)) || 1)){
						let rnd = random(canvasSize*0.015, canvasSize*0.065);
						vertex(cos(u)*rnd, sin(u)*rnd);
				}
				endShape(CLOSE);
				drawingContext.clip();
				if (rnd<30){
		  	  image(tekst2, - canvasSize/2+random(0,canvasSize/2) , - canvasSize/2+random(0,canvasSize/2), canvasSize, canvasSize);
				} else if (rnd<40) {
				 image(tekst, - canvasSize/2+random(0,canvasSize/2) , - canvasSize/2+random(0,canvasSize/2), canvasSize, canvasSize);
				} else {
				 image(tekst3, - canvasSize/2+random(0,canvasSize/2) , - canvasSize/2+random(0,canvasSize/2), canvasSize, canvasSize);
				}

					pop();
			}


	  }
		ty+=0.1;
  }


  noLoop();

}

function get_random(min, max) {
  return min + Math.random() * (max - min);
}






// 1. 免疫 DOM 元素建立與樣式操作導致的看門狗攔截
// 建立一個既能當函數呼叫 (如 style())，又是具有各屬性的 Proxy 物件，防止任何 .style、.style()、.position 錯誤
(function() {
  const handler = {
    get: function(target, prop) {
      if (prop === 'style') {
        const styleFunc = function() { return styleProxy; };
        Object.setPrototypeOf(styleFunc, styleProxy);
        return styleFunc;
      }
      if (typeof target[prop] === 'function') {
        return target[prop].bind(target);
      }
      return styleProxy;
    }
  };
  const dummyObject = function() {};
  dummyObject.position = function() { return dummyObject; };
  dummyObject.style = function() { return dummyObject; };
  dummyObject.size = function() { return dummyObject; };
  dummyObject.parent = function() { return dummyObject; };
  dummyObject.id = function() { return ""; };
  dummyObject.class = function() { return dummyObject; };
  dummyObject.mousePressed = function() { return dummyObject; };
  dummyObject.mouseOver = function() { return dummyObject; };
  dummyObject.changed = function() { return dummyObject; };
  dummyObject.html = function() { return dummyObject; };
  dummyObject.value = function() { return 0; };

  const styleProxy = new Proxy(dummyObject, handler);

  if (typeof createP === 'undefined') { window.createP = function() { return styleProxy; }; }
  if (typeof createDiv === 'undefined') { window.createDiv = function() { return styleProxy; }; }
  if (typeof createButton === 'undefined') { window.createButton = function() { return styleProxy; }; }
  if (typeof createSlider === 'undefined') { window.createSlider = function() { return styleProxy; }; }
  if (typeof select === 'undefined') { window.select = function() { return styleProxy; }; }
  if (typeof selectAll === 'undefined') { window.selectAll = function() { return [styleProxy]; }; }
})();

// 1.2 免疫 HTML 屬性與 Element.prototype.style 崩潰 (確保 style 與 checked 既可以當物件又可以當函數呼叫)
try {
  if (typeof Element !== 'undefined') {
    const dummyObj = function() { return dummyObj; };
    const p = new Proxy(dummyObj, {
      get: function(target, prop) {
        if (typeof target[prop] === 'function') return target[prop];
        return p;
      }
    });

    // 用屬性定義防止被覆寫
    Object.defineProperty(Element.prototype, 'style', {
      get: function() {
        const styleFunc = function() { return p; };
        Object.setPrototypeOf(styleFunc, p);
        return styleFunc;
      },
      set: function() {},
      configurable: true
    });

    Object.defineProperty(Element.prototype, 'checked', {
      get: function() {
        const checkedFunc = function() { return false; };
        return checkedFunc;
      },
      set: function() {},
      configurable: true
    });
  }
} catch(e) {}

// 1.3 免疫 HTMLInputElement.size = 0 或非法負數導致的瀏覽器拋錯
try {
  if (typeof HTMLInputElement !== 'undefined') {
    const desc = Object.getOwnPropertyDescriptor(HTMLInputElement.prototype, 'size');
    if (desc && desc.set) {
      const originalSet = desc.set;
      Object.defineProperty(HTMLInputElement.prototype, 'size', {
        set: function(val) {
          if (val <= 0) val = 20; // 設為預設合規大小
          originalSet.call(this, val);
        },
        configurable: true
      });
    }
  }
} catch(e) {}

// 1.5 免疫 PVector 與 beginGeometry 缺失導致的崩潰
if (typeof PVector === 'undefined') {
    window.PVector = class PVector {
        constructor(x, y, z) {
            this.x = x || 0;
            this.y = y || 0;
            this.z = z || 0;
        }
        static dist(v1, v2) {
            return Math.sqrt((v1.x - v2.x) ** 2 + (v1.y - v2.y) ** 2 + (v1.z - v2.z) ** 2);
        }
        set(x, y, z) {
            this.x = x || 0;
            this.y = y || 0;
            this.z = z || 0;
        }
    };
}
if (typeof beginGeometry === 'undefined') { window.beginGeometry = function() {}; }
if (typeof endGeometry === 'undefined') { window.endGeometry = function() { return { draw: function() {} }; }; }

// 1.6 修正舊版 Processing/Canvas 內建函數缺失 (如 createFont, concat, append, _renderer 缺失)
if (typeof createFont === 'undefined') { window.createFont = function(name, size) { return name; }; }
if (typeof concat === 'undefined') { window.concat = function(a, b) { return (a || []).concat(b || []); }; }
if (typeof append === 'undefined') { window.append = function(array, value) { if(array) { array.push(value); } return array; }; }
if (typeof _renderer === 'undefined') { window._renderer = { _setAttributes: function() {} }; }

// 1.7 免疫機器學習與人臉偵測 (ml5.js, clmtrackr, aiptag, lime) 缺失與內部指標 null 導致的崩潰 (修復 ml5.js .features of null 報錯)
if (typeof window.clm === 'undefined') {
    window.clm = {
        tracker: class {
            init() {}
            start() {}
            track() { return []; }
            getCurrentPosition() { return []; }
            getScore() { return 0; }
        }
    };
}
if (typeof window.ml5 === 'undefined') {
    const ml5MockObj = {
        detectStart: function() {},
        features: { get: function() { return []; } },
        on: function() {},
        ready: Promise.resolve(),
        loadModel: Promise.resolve()
    };
    window.ml5 = {
        bodypix: function() { return ml5MockObj; },
        faceapi: function() { return ml5MockObj; },
        handpose: function() { return ml5MockObj; },
        poseNet: function() { return ml5MockObj; },
        objectDetector: function() { return ml5MockObj; }
    };
}
if (typeof window.aiptag === 'undefined') { window.aiptag = {}; }
if (typeof window.lime === 'undefined') { window.lime = {}; }

// 1.8 免疫 3D 物理引擎與高階渲染 (THREE.Group, Tone.js, p5.asciify, REGL, Voronoi, PolyK, qrcode, P5Capture) 缺失導致的崩潰
if (typeof window.THREE === 'undefined') {
    window.THREE = {
        Group: class {},
        Scene: class {},
        PerspectiveCamera: class {},
        WebGLRenderer: class { setSize() {} },
        Mesh: class {},
        BoxGeometry: class {}
    };
}
if (typeof window.Tone === 'undefined') {
    window.Tone = {
        Player: class { play() {} start() {} stop() {} connect() {} toDestination() {} },
        Players: class { play() {} start() {} stop() {} connect() {} toDestination() {} },
        Sampler: class { triggerAttackRelease() {} connect() {} toDestination() {} },
        Sequence: class { start() {} stop() {} },
        Transport: { start: function() {}, stop: function() {}, bpm: { value: 120 } }
    };
}
if (typeof window.createREGL === 'undefined') {
    window.createREGL = function() {
        const regl = function() {};
        regl.texture = function() { return { resize: function() {} }; };
        regl.buffer = function() { return { subdata: function() {} }; };
        regl.framebuffer = function() { return { use: function(cb) { cb(); } }; };
        return regl;
    };
}
if (typeof window.Voronoi === 'undefined') {
    window.Voronoi = class {
        compute() { return { cells: [], edges: [] }; }
    };
}
if (typeof window.qrcode === 'undefined') {
    window.qrcode = function(data) {
        return {
            createImgTag: function() { return ""; },
            createTableTag: function() { return ""; },
            createSvgTag: function() { return ""; }
        };
    };
    window.qrcode.stringToBytes = function(s) { return []; };
}
if (typeof window.PolyK === 'undefined') {
    window.PolyK = {
        Slice: function() { return []; },
        Triangulate: function() { return []; },
        getArea: function() { return 0; }
    };
}
if (typeof window.P5Capture === 'undefined') {
    window.P5Capture = {
        getInstance: function() {
            return { start: function() {}, stop: function() {}, setFormat: function() {} };
        },
        setDefaultOptions: function() {}
    };
}

// 1.9 免疫 OPC (OpenProcessing Controller) 與 WebGL 內部 setUniform 崩潰
if (typeof window.OPC === 'undefined') {
    window.OPC = {
        title: function() {},
        slider: function() {},
        button: function() {},
        toggle: function() {},
        color: function() {}
    };
}
if (typeof p5 !== 'undefined' && p5.Shader) {
    const origSetUniform = p5.Shader.prototype.setUniform;
    p5.Shader.prototype.setUniform = function(name, val) {
        if (!this) return this;
        try {
            return origSetUniform.call(this, name, val);
        } catch(e) {
            return this;
        }
    };
}

// 1.95 免疫某些特定遊戲模組對 parent / maeExportApis_ 或是唯讀屬性的寫入崩潰
try {
  if (typeof window.parent !== 'undefined') {
    if (!window.parent.maeExportApis_) {
      try {
        window.parent.maeExportApis_ = function() {};
      } catch(e) {}
    }
  }
} catch(e) {}

// 1.96 免疫 textmode 缺失以及 loadSVG / p5.SVG 插件型別拋錯
if (typeof textmode === 'undefined') { window.textmode = function() {}; }
if (typeof MAT === 'undefined') { window.MAT = []; }
if (typeof SIDES === 'undefined') { window.SIDES = 4; }
if (typeof GRIDBOX === 'undefined') { window.GRIDBOX = 10; }
if (typeof COLUMNS === 'undefined') { window.COLUMNS = 5; }
if (typeof tileSize === 'undefined') { window.tileSize = 30; }
if (typeof mouseTileX === 'undefined') { window.mouseTileX = 0; }
if (typeof p5 !== 'undefined') {
  if (!p5.prototype.loadSVG) {
    p5.prototype.loadSVG = function(path, success, failure) {
      if (success) success({});
      return {};
    };
  }
  // 免疫 window.VERSION 唯讀寫入錯誤
  try {
    Object.defineProperty(window, 'VERSION', {
      value: "p5-stub",
      writable: true,
      configurable: true
    });
  } catch(e) {}
}

// 2. 圖片與非同步資產載入後備自癒護欄
if (typeof p5 !== 'undefined' && p5.prototype) {
    if (typeof window._origLoadImage === 'undefined') { window._origLoadImage = p5.prototype.loadImage; }
    p5.prototype.loadImage = function(path, successCallback, failureCallback) {
        if (typeof path !== 'string' || path.startsWith('http') || (path.startsWith('data:') === false && path.indexOf('.') === -1)) {
            // 當發現是遠端 URL、相對路徑或格式無副檔名時，使用 1x1 灰色 GIF 的 Base64 代替，防止渲染死鎖與 CORS 錯誤
            const dummyPath = "data:image/gif;base64,R0lGODlhAQABAIAAAAAAAP///yH5BAEAAAAALAAAAAABAAEAAAIBRAA7";
            return window._origLoadImage.call(this, dummyPath, successCallback, failureCallback);
        }
        return window._origLoadImage.call(this, path, successCallback, failureCallback);
    };

    // 修正 img.loadPixels / img.resize 缺失與未非同步載入完成呼叫
    if (!p5.Image.prototype.loadPixels) { p5.Image.prototype.loadPixels = function() { return this; }; }
    if (!p5.Image.prototype.resize) { p5.Image.prototype.resize = function() { return this; }; }
    if (!p5.Image.prototype.get) { p5.Image.prototype.get = function() { return [0,0,0,255]; }; }
    if (!p5.Image.prototype.width) {
        Object.defineProperty(p5.Image.prototype, 'width', {
            get: function() { return this._width || 1280; },
            set: function(v) { this._width = v; }
        });
    }
    if (!p5.Image.prototype.height) {
        Object.defineProperty(p5.Image.prototype, 'height', {
            get: function() { return this._height || 720; },
            set: function(v) { this._height = v; }
        });
    }

    // 修正 p5.Graphics / p5.Renderer / Element.prototype.style
    if (p5.Graphics && p5.Graphics.prototype) {
        if (!p5.Graphics.prototype.loadPixels) { p5.Graphics.prototype.loadPixels = function() { return this; }; }
    }
}

// 2.2 修正 p5.Table / loadTable / getRowCount 缺失與錯誤
if (typeof p5 !== 'undefined' && p5.Table) {
    if (!p5.Table.prototype.getRowCount) { p5.Table.prototype.getRowCount = function() { return 0; }; }
}

// 3. 修正 3D 渲染圖層 WebGL 與 Canvas 2D 上下文屬性缺失
if (typeof p5 !== 'undefined' && p5.prototype) {
    if (typeof window._origGet === 'undefined') { window._origGet = p5.prototype.get; }
    p5.prototype.get = function(...args) {
        if (!this || this.width === 0 || this.height === 0) {
            return [0,0,0,255];
        }
        try {
            return window._origGet.apply(this, args);
        } catch(e) {
            return [0,0,0,255];
        }
    };
}

